import { Avatar } from '@refy-design/web';
import { Badge } from '@refy-design/web';
import { KanbanCard } from '@refy-design/web';
import { Modal } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
export function Example() {
  const args: Pick<ComponentProps<typeof KanbanCard>, 'item'> = {
    item: {
      id: 'review',
      title: 'Review documentation',
      description: 'Check the guidelines and share the review with the team.',
      meta: (
        <>
          <Badge tone="warn">High priority</Badge>
          <span>Oct 23</span>
        </>
      ),
      footer: (
        <>
          <span>2 attachments · 5 comments</span>
          <Avatar size="xs" initials="AS" alt="Ana Silva" />
        </>
      ),
    },
  };
  const [open, setOpen] = useState(false);
  return (
    <>
      <KanbanCard {...args} style={{ maxWidth: 320 }} onOpen={() => setOpen(true)} />
      <Modal open={open} onClose={() => setOpen(false)} title={args.item.title}>
        {args.item.description}
      </Modal>
    </>
  );
}

